import * as THREE from 'three'
import { useEffect, useMemo, useRef, useState } from 'react'
import { Canvas, useFrame, useThree } from '@react-three/fiber'

/**
 * Three.js (R3F) scroll hero.
 * Hero = one solid sphere. Field = ball-and-stick molecules + hover. Horizontal nanopore.
 */

const heroTarget = new THREE.Vector3()
const cameraTarget = new THREE.Vector3()
const lookAtTarget = new THREE.Vector3()
const poreScale = new THREE.Vector3(1, 1, 1)
const _up = new THREE.Vector3(0, 1, 0)
const _dir = new THREE.Vector3()
const _quat = new THREE.Quaternion()

const ATOM = {
  aqua: '#6eb8b8',
  lime: '#a8c85a',
  blue: '#5aa0c8',
  teal: '#4a9e98',
  soft: '#8ec8c0',
}
const BOND = '#7ab0a8'

const clamp = (v, min = 0, max = 1) => Math.min(Math.max(v, min), max)
const smooth = (start, end, value) => {
  const n = clamp((value - start) / (end - start))
  return n * n * (3 - 2 * n)
}
const lerp = THREE.MathUtils.lerp

const BEATS = {
  focusStart: 0.06,
  focusEnd: 0.3,
  poreInStart: 0.26,
  poreInEnd: 0.38,
  transitStart: 0.38,
  transitEnd: 0.66,
  clearStart: 0.52,
  clearEnd: 0.7,
  poreOutStart: 0.66,
  poreOutEnd: 0.78,
  brandStart: 0.76,
  brandEnd: 0.9,
}

function seededRandom(seed) {
  const x = Math.sin(seed * 127.1 + 311.7) * 43758.5453
  return x - Math.floor(x)
}

function bondQuaternion(dirArr) {
  _dir.set(dirArr[0], dirArr[1], dirArr[2]).normalize()
  return _quat.setFromUnitVectors(_up, _dir).clone()
}

const TIP_SETS = [
  [
    { pos: [0.52, 0.3, 0.16], color: ATOM.lime, r: 0.18 },
    { pos: [-0.46, 0.26, 0.2], color: ATOM.aqua, r: 0.16 },
    { pos: [0.1, -0.48, 0.18], color: ATOM.lime, r: 0.15 },
    { pos: [-0.08, 0.12, -0.5], color: ATOM.blue, r: 0.17 },
    { pos: [0.38, -0.16, -0.32], color: ATOM.soft, r: 0.14 },
  ],
  [
    { pos: [0.48, 0.36, 0], color: ATOM.blue, r: 0.16 },
    { pos: [-0.46, 0.32, 0.14], color: ATOM.lime, r: 0.15 },
    { pos: [0, -0.46, 0.22], color: ATOM.aqua, r: 0.18 },
    { pos: [0.18, 0.08, -0.48], color: ATOM.lime, r: 0.14 },
  ],
  [
    { pos: [0.44, 0.22, 0.28], color: ATOM.aqua, r: 0.15 },
    { pos: [-0.38, 0.36, -0.1], color: ATOM.lime, r: 0.17 },
    { pos: [0.12, -0.42, -0.22], color: ATOM.blue, r: 0.16 },
    { pos: [-0.28, -0.18, 0.44], color: ATOM.soft, r: 0.14 },
    { pos: [0.32, 0.04, -0.42], color: ATOM.lime, r: 0.13 },
  ],
]

/** Shared scroll progress — updated outside React render loop */
const progressApi = {
  current: 0,
  target: 0,
}

export default function App() {
  const [ui, setUi] = useState({ brand: 0, hint: 1 })

  useEffect(() => {
    const onScroll = () => {
      const scrollable = document.documentElement.scrollHeight - window.innerHeight
      progressApi.target = scrollable > 0 ? clamp(window.scrollY / scrollable) : 0
    }
    onScroll()
    window.addEventListener('scroll', onScroll, { passive: true })
    window.addEventListener('resize', onScroll)

    let raf = 0
    let lastUi = -1
    const tick = () => {
      progressApi.current = lerp(progressApi.current, progressApi.target, 0.09)
      if (Math.abs(progressApi.current - progressApi.target) < 0.0002) {
        progressApi.current = progressApi.target
      }
      // UI overlays only — do NOT drive the whole Canvas through React state
      const brand = smooth(BEATS.brandStart, BEATS.brandEnd, progressApi.current)
      const hint = 1 - smooth(0.02, 0.1, progressApi.current)
      const key = Math.round(brand * 40) + Math.round(hint * 40) * 100
      if (key !== lastUi) {
        lastUi = key
        setUi({ brand, hint })
      }
      raf = requestAnimationFrame(tick)
    }
    raf = requestAnimationFrame(tick)

    return () => {
      window.removeEventListener('scroll', onScroll)
      window.removeEventListener('resize', onScroll)
      cancelAnimationFrame(raf)
    }
  }, [])

  return (
    <main className="experience-shell">
      <div className="gradient-orb gradient-orb-a" aria-hidden />
      <div className="gradient-orb gradient-orb-b" aria-hidden />
      <div className="gradient-orb gradient-orb-c" aria-hidden />

      <div className="canvas-stage">
        <Canvas
          dpr={[1, 1.5]}
          camera={{ position: [0, 1.4, 11], fov: 38, near: 0.1, far: 80 }}
          gl={{ antialias: true, alpha: true, powerPreference: 'high-performance' }}
          onCreated={({ gl }) => {
            gl.setClearColor(0x000000, 0)
            gl.toneMapping = THREE.ACESFilmicToneMapping
            gl.toneMappingExposure = 1.05
          }}>
          <fog attach="fog" args={['#0a4550', 18, 40]} />
          <ambientLight intensity={0.75} color="#c8fff0" />
          <directionalLight position={[5, 9, 6]} intensity={1.7} color="#ffffff" />
          <directionalLight position={[-6, 1, 3]} intensity={0.65} color="#5eb0c0" />
          <pointLight position={[0, 3, 5]} intensity={0.9} color="#9fe8d8" distance={28} />

          <CameraRig />
          <FieldMolecules />
          <HeroSphere />
          <Nanopore />
        </Canvas>

        <div className="scroll-hint" style={{ opacity: ui.hint }}>
          Scroll to follow the molecule
        </div>

        <div className="brand-reveal" style={{ opacity: ui.brand }}>
          <div className="brand-name">
            AAGAMI
            <span>
              SE
              <span className="brand-q">
                Q
                <i className="brand-q-dot" aria-hidden />
              </span>
            </span>
          </div>
          <p className="brand-tagline">Clarity in the fight against cancer</p>
        </div>
      </div>
      <div className="scroll-space" aria-hidden />
    </main>
  )
}

function CameraRig() {
  const { camera } = useThree()

  useFrame((_, delta) => {
    const progress = progressApi.current
    const focus = smooth(BEATS.focusStart, BEATS.focusEnd, progress)
    const transit = smooth(BEATS.transitStart, BEATS.transitEnd, progress)
    const brand = smooth(BEATS.brandStart, BEATS.brandEnd, progress)

    const camY = lerp(1.2, 2.7, transit) * (1 - brand * 0.8) + lerp(0.35, 0.15, brand)
    const camZ = lerp(11.5, 8.5, focus)
    const throughZ = lerp(camZ, 7.6, transit)
    const finalZ = lerp(throughZ, 6.5, brand)

    cameraTarget.set(lerp(0.35, 0, focus) * (1 - brand), camY, finalZ)
    lookAtTarget.set(0, lerp(1.1, -0.4, transit) * (1 - brand * 0.65), 0)

    const ease = 1 - Math.exp(-delta * 3.6)
    camera.position.lerp(cameraTarget, ease)
    camera.lookAt(lookAtTarget)
    camera.fov = lerp(38, 31, focus)
    camera.updateProjectionMatrix()
  })

  return null
}

function AtomMat({ color, emissiveIntensity = 0.28 }) {
  return (
    <meshStandardMaterial
      color={color}
      emissive={color}
      emissiveIntensity={emissiveIntensity}
      metalness={0.22}
      roughness={0.32}
    />
  )
}

/** Ball-and-stick molecule (MP4 vibe — not bubbles) */
function MoleculeMesh({ palette = 0 }) {
  const tips = TIP_SETS[palette % TIP_SETS.length]
  const core = palette === 1 ? ATOM.blue : ATOM.aqua

  return (
    <group>
      <mesh>
        <sphereGeometry args={[0.28, 24, 24]} />
        <AtomMat color={core} emissiveIntensity={0.35} />
      </mesh>
      {tips.map((tip, i) => {
        const mid = [tip.pos[0] * 0.5, tip.pos[1] * 0.5, tip.pos[2] * 0.5]
        const length = Math.hypot(tip.pos[0], tip.pos[1], tip.pos[2]) * 0.7
        return (
          <group key={i}>
            <mesh position={mid} quaternion={bondQuaternion(tip.pos)}>
              <cylinderGeometry args={[0.038, 0.038, length, 8]} />
              <meshStandardMaterial color={BOND} roughness={0.45} metalness={0.15} />
            </mesh>
            <mesh position={tip.pos}>
              <sphereGeometry args={[tip.r, 18, 18]} />
              <AtomMat color={tip.color} />
            </mesh>
          </group>
        )
      })}
    </group>
  )
}

function FieldMolecules() {
  const group = useRef()
  const layout = useMemo(() => {
    const items = []
    for (let i = 0; i < 42; i += 1) {
      items.push({
        base: [
          (seededRandom(i + 2) - 0.5) * 15,
          0.7 + seededRandom(i + 18) * 4.8,
          (seededRandom(i + 33) - 0.5) * 11,
        ],
        scale: 0.55 + seededRandom(i + 48) * 0.7,
        drift: 0.3 + seededRandom(i + 61) * 0.65,
        phase: seededRandom(i + 77) * Math.PI * 2,
        palette: i % 3,
      })
    }
    return items
  }, [])

  useFrame((state) => {
    if (!group.current) return
    const progress = progressApi.current
    const t = state.clock.elapsedTime
    const clear = smooth(BEATS.clearStart, BEATS.clearEnd, progress)
    const focus = smooth(BEATS.focusStart, BEATS.focusEnd, progress)
    const fade = (1 - focus * 0.28) * (1 - clear)

    group.current.visible = fade > 0.04
    group.current.children.forEach((child, i) => {
      const item = layout[i]
      if (!item) return
      const bob = Math.sin(t * item.drift + item.phase) * 0.22
      const driftX = Math.cos(t * item.drift * 0.7 + item.phase) * 0.28
      child.position.set(item.base[0] + driftX, item.base[1] + bob, item.base[2])
      child.rotation.x = t * 0.07 * item.drift
      child.rotation.y = t * 0.11 * item.drift + item.phase
      const hover = child.userData.hoverAmt || 0
      child.scale.setScalar(item.scale * fade * (1 + hover * 0.35))
    })
  })

  return (
    <group ref={group}>
      {layout.map((item, i) => (
        <HoverMolecule key={i} item={item} />
      ))}
    </group>
  )
}

function HoverMolecule({ item }) {
  const root = useRef()
  const hoverAmt = useRef(0)
  const hovered = useRef(false)

  useFrame((_, delta) => {
    if (!root.current) return
    hoverAmt.current = lerp(hoverAmt.current, hovered.current ? 1 : 0, 1 - Math.exp(-delta * 10))
    root.current.userData.hoverAmt = hoverAmt.current
    root.current.traverse((obj) => {
      if (obj.isMesh && obj.material && obj.material.emissiveIntensity != null) {
        const base = obj.userData.baseEmissive ?? 0.28
        obj.userData.baseEmissive = base
        obj.material.emissiveIntensity = base + hoverAmt.current * 0.9
      }
    })
  })

  return (
    <group
      ref={root}
      onPointerOver={(e) => {
        e.stopPropagation()
        hovered.current = true
        document.body.style.cursor = 'pointer'
      }}
      onPointerOut={() => {
        hovered.current = false
        document.body.style.cursor = 'auto'
      }}>
      <MoleculeMesh palette={item.palette} />
    </group>
  )
}

/** Single solid hero sphere — not a bubble */
function HeroSphere() {
  const mesh = useRef()
  const mat = useRef()
  const hovered = useRef(false)
  const hoverAmt = useRef(0)

  useFrame((state, delta) => {
    if (!mesh.current || !mat.current) return
    const progress = progressApi.current
    const t = state.clock.elapsedTime
    const focus = smooth(BEATS.focusStart, BEATS.focusEnd, progress)
    const transit = smooth(BEATS.transitStart, BEATS.transitEnd, progress)
    const brand = smooth(BEATS.brandStart, BEATS.brandEnd, progress)
    hoverAmt.current = lerp(hoverAmt.current, hovered.current ? 1 : 0, 1 - Math.exp(-delta * 10))

    if (progress < BEATS.transitStart) {
      heroTarget.set(
        lerp(2.2, 0, focus) + Math.sin(t * 0.4) * 0.07 * (1 - focus),
        lerp(1.7, 2.05, focus) + Math.cos(t * 0.5) * 0.05 * (1 - focus),
        lerp(1.0, 0.12, focus),
      )
    } else if (progress < BEATS.poreOutEnd) {
      heroTarget.set(0, lerp(2.05, -2.25, transit), 0.1)
    } else {
      heroTarget.set(lerp(0, 1.55, brand), lerp(-2.25, 0.06, brand), lerp(0.1, 0.25, brand))
    }

    mesh.current.position.lerp(heroTarget, 1 - Math.exp(-delta * 5.2))
    const size =
      lerp(0.38, 0.62, focus) * lerp(1, 0.85, transit * 0.35) * lerp(1, 0.26, brand) * (1 + hoverAmt.current * 0.1)
    mesh.current.scale.setScalar(size)
    mat.current.emissiveIntensity = 0.4 + focus * 0.45 + hoverAmt.current * 0.7
  })

  return (
    <mesh
      ref={mesh}
      onPointerOver={(e) => {
        e.stopPropagation()
        hovered.current = true
        document.body.style.cursor = 'pointer'
      }}
      onPointerOut={() => {
        hovered.current = false
        document.body.style.cursor = 'auto'
      }}>
      <sphereGeometry args={[1, 48, 48]} />
      <meshStandardMaterial
        ref={mat}
        color="#4ec4b8"
        emissive="#2aa898"
        emissiveIntensity={0.4}
        metalness={0.35}
        roughness={0.28}
      />
    </mesh>
  )
}

function Nanopore() {
  const group = useRef()
  const sheet = useRef()
  const rim = useRef()
  const glow = useRef()

  const nodes = useMemo(() => {
    const list = []
    for (let i = 0; i < 56; i += 1) {
      const a = (i / 56) * Math.PI * 2 + seededRandom(i) * 0.12
      const r = 1.3 + seededRandom(i + 3) * 3.5
      list.push([Math.cos(a) * r, 0.02, Math.sin(a) * r])
    }
    for (let i = 0; i < 20; i += 1) {
      const x = (seededRandom(i + 50) - 0.5) * 8.5
      const z = (seededRandom(i + 80) - 0.5) * 8.5
      if (Math.hypot(x, z) < 1.2) continue
      list.push([x, 0.015, z])
    }
    return list
  }, [])

  useFrame((state, delta) => {
    if (!group.current) return
    const progress = progressApi.current
    const visible =
      smooth(BEATS.poreInStart, BEATS.poreInEnd, progress) * (1 - smooth(BEATS.poreOutStart, BEATS.poreOutEnd, progress))

    const pulse = 1 + Math.sin(state.clock.elapsedTime * 1.35) * 0.01
    poreScale.set(pulse, 1, pulse)
    group.current.scale.lerp(poreScale, 1 - Math.exp(-delta * 4))
    group.current.visible = visible > 0.01
    if (sheet.current) sheet.current.opacity = visible * 0.8
    if (rim.current) rim.current.opacity = visible
    if (glow.current) glow.current.opacity = visible * 0.38
  })

  return (
    <group ref={group}>
      <mesh rotation={[-Math.PI / 2, 0, 0]}>
        <ringGeometry args={[1.05, 5.6, 128]} />
        <meshStandardMaterial
          ref={sheet}
          color="#5fa8a0"
          emissive="#1a504c"
          emissiveIntensity={0.2}
          metalness={0.3}
          roughness={0.42}
          transparent
          side={THREE.DoubleSide}
          depthWrite={false}
        />
      </mesh>
      <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, 0.012, 0]}>
        <ringGeometry args={[1.02, 1.18, 96]} />
        <meshStandardMaterial
          ref={rim}
          color="#4ecfc0"
          emissive="#2ab8a8"
          emissiveIntensity={1.35}
          metalness={0.35}
          roughness={0.22}
          transparent
          side={THREE.DoubleSide}
        />
      </mesh>
      <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, -0.01, 0]}>
        <ringGeometry args={[1.14, 1.55, 96]} />
        <meshBasicMaterial ref={glow} color="#6ee8d8" transparent side={THREE.DoubleSide} depthWrite={false} />
      </mesh>
      {nodes.map((pos, i) => (
        <mesh key={i} position={pos}>
          <sphereGeometry args={[0.032 + seededRandom(i) * 0.018, 8, 8]} />
          <meshStandardMaterial color="#8ec8c0" emissive="#2a7068" emissiveIntensity={0.15} roughness={0.4} />
        </mesh>
      ))}
    </group>
  )
}
